import React, { forwardRef } from 'react';
import { isElement } from 'react-is';

import { Content } from './Content.js';
import { InformationOverlayContext } from './contexts/InformationOverlayContext.js';
import { Trigger } from './Trigger.js';
import { _useAriaLabelingProps } from '../../core/hooks/useAriaLabelingProps.js';
import { useBreakpoint } from '../../core/hooks/useBreakpoint.js';
import { _useControllableState } from '../../core/hooks/useControllableState.js';
import { _useId } from '../../core/hooks/useId.js';
import { useMergeRefs } from '../../core/hooks/useMergeRefs.js';
import type { AriaLabelingProps } from '../../core/types/a11y-props.js';
import type { RoleVariantType } from '../../core/types/role-variant.js';
import type { WithChildren } from '../../core/types/with-children.js';
import { Flex } from '../../layouts-core/flex/Flex.js';
import { useOverlayWithTrigger } from '../hooks/useOverlayWithTrigger.js';
import { Overlay } from '../overlay/Overlay.js';
import { basePlacementsType } from '../types/placement.js';

// #region Typings
/** Accepted properties for InformationOverlay */
export interface InformationOverlayBaseProps
  extends AriaLabelingProps,
    WithChildren {
  /**
   * The preferred placement for the overlay if there is enough space. If the preferred placement is not possible, the overlay will be positioned according to the available space.
   * @defaultValue 'bottom'
   */
  placement?: basePlacementsType;
  /**
   * Determines the styling and the trigger icon.
   * @defaultValue 'info'
   */
  variant?: RoleVariantType;
}

export interface InformationOverlayUncontrolledProps {
  /**
   * Determines whether or not the overlay is initially opened in an uncontrolled scenario.
   * @defaultValue false
   */
  defaultOpen?: boolean;
  /**
   * Determines whether or not the overlay is open in a controlled scenario.
   */
  open?: never;
  /**
   * Callback fired when the open attribute changes in a controlled scenario.
   */
  onOpenChange?: never;
}

export interface InformationOverlayControlledProps {
  /**
   * Determines whether or not the overlay is initially opened in an uncontrolled scenario.
   */
  defaultOpen?: never;
  /**
   * Determines whether or not the overlay is open in a controlled scenario.
   */
  open: boolean;
  /**
   * Callback fired when the open attribute changes in a controlled scenario.
   */
  onOpenChange: (isOpen: boolean) => void;
}

/** Accepted properties for InformationOverlay */
export type InformationOverlayProps = InformationOverlayBaseProps &
  (InformationOverlayUncontrolledProps | InformationOverlayControlledProps);

type InformationOverlaySlots = {
  trigger?: React.ReactElement;
  content?: React.ReactElement;
};
// #endregion Typings

export const _InformationOverlay = forwardRef<
  HTMLButtonElement,
  InformationOverlayProps
>((props, forwardedRef) => {
  const {
    children,
    defaultOpen,
    open,
    onOpenChange,
    variant = 'neutral',
    placement = 'bottom',
    ...remainingProps
  } = props;
  const id = _useId({ prefix: 'information-overlay' });
  const { 'aria-describedby': ariaDescribedBy, ...ariaProps } =
    _useAriaLabelingProps(remainingProps);

  const [isOpen, setIsOpen] = _useControllableState({
    defaultValue: defaultOpen,
    value: open,
    onChange: onOpenChange,
  });

  const {
    targetRef,
    triggerRef,
    overlayRef,
    overlayState,
    overlayProps,
    overlayTriggerProps,
  } = useOverlayWithTrigger({
    placement: `${placement}-start`,
    placementFallbacks: [
      'top-start',
      'bottom-start',
      'right-start',
      'left-start',
    ],
    offset: 4,
    crossOffset: -16,
    widthStrategy: useBreakpoint('(max-width: 480px)')
      ? { max: 300 }
      : { max: 400 },
    open: isOpen,
    onOpenChange: setIsOpen,
    shouldCloseOnBlur: true,
  });

  const rootRef = useMergeRefs([forwardedRef, triggerRef, targetRef]);

  const slots: InformationOverlaySlots = {
    content: undefined,
    trigger: undefined,
  };

  React.Children.forEach(children, (child) => {
    if (isElement(child)) {
      switch (child.type) {
        case Trigger:
          slots.trigger = child;
          break;
        case Content:
          slots.content = child;
          break;
        default:
          // eslint-disable-next-line no-console
          console.warn(
            'Only Trigger and Content are valid children of the InformationOverlay.',
          );
      }
    } else {
      // eslint-disable-next-line no-console
      console.warn(
        'The used child is not supported by the InformationOverlay.',
      );
    }
  });

  return (
    <InformationOverlayContext.Provider
      value={{ variant, overlayTriggerProps, id, isOpen }}
    >
      <Trigger
        ref={rootRef}
        id={slots.trigger?.props?.id}
        aria-label={slots.trigger?.props['aria-label']}
      >
        {slots.trigger?.props.children}
      </Trigger>
      <Overlay
        ref={overlayRef}
        isOpen={overlayState.isOpen}
        overlayProps={overlayProps}
        aria-describedby={ariaDescribedBy ?? id}
        {...ariaProps}
      >
        <Flex paddingY={12} paddingX={16} flexDirection="column">
          {slots.content}
        </Flex>
      </Overlay>
    </InformationOverlayContext.Provider>
  );
});

(
  _InformationOverlay as typeof _InformationOverlay & { displayName: string }
).displayName = 'InformationOverlay';

/**
 * The `InformationOverlay` provides additional information via an overlay, the position of which can be adjusted.
 * According to the type of information, the `variant` can be set. The trigger consists of an icon and an optional text.
 * By default, the `variant` is `info` and the overlay is positioned on the bottom.
 */
export const InformationOverlay = Object.assign(_InformationOverlay, {
  Content,
  Trigger,
});
